import{_ as o,a as t,b as e,c as a,d as r,e as n}from"./chunks/AS-Apps-SA.CzVlwi0n.js";import{_ as s,o as l,c as p,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const I=JSON.parse('{"title":"Impostazioni Android","description":"","frontmatter":{"source_hash":"8a63383c39","source_commit":"e9ebf28"},"headers":[],"relativePath":"it/troubleshoot/savings.md","filePath":"it/troubleshoot/savings.md"}'),d={name:"it/troubleshoot/savings.md"};function u(g,i,z,c,v,h){return l(),p("div",null,[...i[0]||(i[0]=[m('<p>Android offre molte opzioni di risparmio energetico: sono utili per aumentare l&#39;autonomia della batteria, ma possono facilmente colpire funzioni indispensabili per un sistema CGM.</p><p>Tutte le impostazioni descritte qui sotto si trovano nelle impostazioni Android del telefono; il loro aspetto varia molto e dipende dalle personalizzazioni del produttore.</p><img src="'+o+'" style="zoom:75%;"><h2 id="battery-saver" tabindex="-1">Risparmio batteria <a class="header-anchor" href="#battery-saver" aria-label="Permalink to &quot;Risparmio batteria {#battery-saver}&quot;">​</a></h2><p>Quando la batteria scende sotto un certo livello, Android chiude molti servizi e impedisce a xDrip di funzionare normalmente. Porta sempre con te un power bank per evitare questa situazione.</p><p>Durante il normale uso del telefono, assicurati che <strong>non</strong> sia attivo.</p><img src="'+t+'" style="zoom:75%;"><h2 id="apps-battery-savings" tabindex="-1">Risparmio batteria delle app <a class="header-anchor" href="#apps-battery-savings" aria-label="Permalink to &quot;Risparmio batteria delle app {#apps-battery-savings}&quot;">​</a></h2><p>Ogni app del telefono può essere personalizzata per quanto riguarda il risparmio della batteria. Se incontri problemi, controlla attentamente queste impostazioni. Vale anche per OOP, WatchDrip+ (se lo usi) e Bluetooth.</p><div class="warning custom-block"><p class="custom-block-title">Aggiornamenti di Android</p><p>Gli aggiornamenti potrebbero riportare queste impostazioni ai valori predefiniti: ricontrollale sempre dopo.</p></div><h4 id="android-10" tabindex="-1">Android 10 <a class="header-anchor" href="#android-10" aria-label="Permalink to &quot;Android 10 {#android-10}&quot;">​</a></h4><img src="'+e+'" style="zoom:75%;"><h4 id="android-11-and-above" tabindex="-1">Android 11 e superiori <a class="header-anchor" href="#android-11-and-above" aria-label="Permalink to &quot;Android 11 e superiori {#android-11-and-above}&quot;">​</a></h4><img src="'+a+'" style="zoom:75%;"><p>xDrip deve funzionare senza restrizioni.</p><img src="'+r+'" style="zoom:75%;"><h3 id="bluetooth" tabindex="-1">Bluetooth <a class="header-anchor" href="#bluetooth" aria-label="Permalink to &quot;Bluetooth {#bluetooth}&quot;">​</a></h3><p>Molto probabilmente troverai Bluetooth tra le app di sistema (menu a tre puntini).<br> Alcuni telefoni Android non mostrano l&#39;app Bluetooth.</p><img src="'+n+'" style="zoom:75%;"><p>Bluetooth deve funzionare senza restrizioni se xDrip si collega direttamente a un sensore.</p><h2 id="xiaomi-miui-optimizations" tabindex="-1">Ottimizzazioni MIUI di Xiaomi <a class="header-anchor" href="#xiaomi-miui-optimizations" aria-label="Permalink to &quot;Ottimizzazioni MIUI di Xiaomi {#xiaomi-miui-optimizations}&quot;">​</a></h2><p>Le ottimizzazioni MIUI possono avere un impatto enorme (in senso negativo) sulla stabilità del sistema e sull&#39;affidabilità di xDrip. Se noti un aumento delle &quot;letture mancate&quot; con MIUI 14 (o forse con versioni MIUI precedenti), prova a disattivare le ottimizzazioni MIUI. Questa impostazione si trova nelle &amp;lt;Opzioni sviluppatore&gt;, nascoste per impostazione predefinita. Qui sotto trovi come mostrare le &amp;lt;Opzioni sviluppatore&gt; e poi disattivare le ottimizzazioni MIUI.</p><h3 id="enable-developer-options" tabindex="-1">Attivare le opzioni sviluppatore <a class="header-anchor" href="#enable-developer-options" aria-label="Permalink to &quot;Attivare le opzioni sviluppatore {#enable-developer-options}&quot;">​</a></h3><p>Per mostrare le <strong>&amp;lt;Opzioni sviluppatore&gt;</strong>, segui questi passaggi:</p><ol><li>Apri le <strong>&amp;lt;Impostazioni&gt;</strong> dello smartphone.</li><li>Seleziona <strong>&amp;lt;Info sul telefono&gt;</strong>.</li><li>Tocca 7 volte <strong>&amp;lt;Versione MIUI&gt;</strong> (prima voce dell&#39;elenco).</li><li>Compare il messaggio <strong>&amp;lt;Ora sei uno sviluppatore.&gt;</strong>.</li><li>Ora è visibile la voce <strong>&amp;lt;Impostazioni&gt;</strong> -&gt; <strong>&amp;lt;Impostazioni aggiuntive&gt;</strong> -&gt; <strong>&amp;lt;Opzioni sviluppatore&gt;</strong>.</li></ol><h3 id="disable-xiaomi-miui-optimizations" tabindex="-1">Disattivare le ottimizzazioni MIUI di Xiaomi <a class="header-anchor" href="#disable-xiaomi-miui-optimizations" aria-label="Permalink to &quot;Disattivare le ottimizzazioni MIUI di Xiaomi {#disable-xiaomi-miui-optimizations}&quot;">​</a></h3><p>Per disattivare le ottimizzazioni MIUI devi prima <strong>attivare le opzioni sviluppatore</strong>. Poi segui questi passaggi:</p><ol><li>Apri le <strong>&amp;lt;Impostazioni&gt;</strong> dello smartphone.</li><li>Seleziona <strong>&amp;lt;Impostazioni aggiuntive&gt;</strong> -&gt; <strong>&amp;lt;Opzioni sviluppatore&gt;</strong>.</li><li><strong>Solo per MIUI 14:</strong> con MIUI 14 l&#39;opzione <strong>&amp;lt;Attiva ottimizzazione MIUI&gt;</strong> <strong>NON</strong> è visibile per impostazione predefinita. Per vederla, scorri fino a <strong>&amp;lt;COMPILAZIONE AUTOMATICA&gt;</strong> e tocca più volte <strong>&amp;lt;Ripristina valori predefiniti&gt;</strong>. L&#39;opzione comparirà.</li><li><strong>Disattiva</strong> l&#39;opzione <strong>&amp;lt;Attiva ottimizzazione MIUI&gt;</strong>!</li><li>Riavvia lo smartphone.</li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.02.26" target="_blank" rel="noreferrer"><em>Ultima modifica 6/03/2024</em></a></p>',30)])])}const _=s(d,[["render",u]]);export{I as __pageData,_ as default};
